const item = $input.first().json || {};
const base = $('Observabilidad — Integrar resultado worker').first().json || {};
const raw = item.output || item.text || item.response || item;

function safeParse(value) {
  if (typeof value === 'object') return value;
  const cleaned = String(value || '{}').replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {
    return {
      asunto_principal: base.intent || 'UNKNOWN',
      puntos_clave: [base.response || 'Sin resumen generado por el modelo.'],
      accion_requerida: base.next_action || 'revision_humana',
      estado_del_caso: base.requires_human ? 'requiere_revision' : 'en_proceso',
      datos_clave: {
        intencion: base.intent || 'UNKNOWN',
        worker_invocado: base.selected_worker || 'none',
        requiere_humano: Boolean(base.requires_human)
      }
    };
  }
}

const parsed = safeParse(raw);

return [{ json: {
  ...base,
  summary_payload: parsed,
  summary_mode: 'llm_mini_after_5_interactions',
  memory_update: {
    resumen_consolidado: `${parsed.asunto_principal}. ${Array.isArray(parsed.puntos_clave) ? parsed.puntos_clave.join(' ') : ''}`.trim(),
    estado_del_caso: parsed.estado_del_caso || (base.requires_human ? 'requiere_revision' : 'en_proceso'),
    datos_clave: parsed.datos_clave || {},
    accion_requerida: parsed.accion_requerida || base.next_action
  }
}}];

const base = $input.first().json || {};
const previous = base.long_term_memory || {};
const priorKeyData = previous.key_data || {};

const datosClave = {
  ...priorKeyData,
  intencion: base.intent,
  worker_invocado: base.selected_worker,
  requiere_humano: Boolean(base.requires_human),
  ultimo_request_id: base.request_id
};

return [{ json: {
  ...base,
  summary_mode: 'minimal_update_under_threshold',
  memory_update: {
    resumen_consolidado: previous.last_summary || `Consulta ${base.intent} procesada por ${base.selected_worker}.`,
    estado_del_caso: base.requires_human ? 'requiere_revision' : (previous.case_status || 'en_proceso'),
    datos_clave: datosClave,
    accion_requerida: base.next_action || 'sin_accion'
  }
}}];
